$('ch').textContent=DATA.channel;const sp=document.createElement('span');sp.textContent=' \xB7 '+DATA.videoTitle;$('ch').appendChild(sp);$('for').textContent=DATA.forWho?'Personalised for '+DATA.forWho:'';
