const secs=c=>{let s=Number(c.seconds);if(!(s>0)&&c.time&&/^\\d+(:\\d{1,2}){1,2}$/.test(c.time))s=c.time.split(':').reduce((a,x)=>a*60+(+x),0);return Number.isFinite(s)&&s>=0?Math.round(s):null};
